INSERT INTO `nf_email_templates` (`template_id`, `key`, `title`, `description`, `placeholders`, `module`, `enabled`, `created_at`, `updated_at`) VALUES
('1', 'user.registration', 'Validation de compte', 'Email de validation envoyé à la création d\'un compte.', '[\"{{username}}\",\"{{site_name}}\",\"{{validation_url}}\"]', 'user', '1', '2026-06-01 10:41:51', '2026-06-01 10:41:51'),
('2', 'user.lost_password', 'Réinitialisation mot de passe', 'Email contenant le lien de réinitialisation du mot de passe.', '[\"{{username}}\",\"{{site_name}}\",\"{{reset_url}}\"]', 'user', '1', '2026-06-01 10:41:51', '2026-06-01 10:41:51'),
('3', 'forum.mention', 'Forum : mention', 'Notification email quand un user est @mentionné dans un sujet/post.', '[\"{{username}}\",\"{{topic_title}}\",\"{{topic_url}}\",\"{{mentioner}}\",\"{{site_name}}\"]', 'forum', '1', '2026-06-01 10:41:51', '2026-06-01 10:41:51'),
('4', 'forum.subscription_reply', 'Forum : nouvelle réponse', 'Notification email quand un sujet abonné reçoit une nouvelle réponse.', '[\"{{username}}\",\"{{topic_title}}\",\"{{topic_url}}\",\"{{author}}\",\"{{site_name}}\"]', 'forum', '1', '2026-06-01 10:41:51', '2026-06-01 10:41:51'),
('5', 'talks.new_message', 'Talks : nouveau message', 'Notification email quand un user reçoit un nouveau MP/message dans un talk.', '[\"{{username}}\",\"{{talk_name}}\",\"{{talk_url}}\",\"{{author}}\",\"{{site_name}}\"]', 'talks', '1', '2026-06-01 10:41:51', '2026-06-01 10:41:51'),
('6', 'moderation.sanction', 'Modération : sanction', 'Email envoyé à un user qui reçoit une sanction (warn/restrict/ban).', '[\"{{username}}\",\"{{site_name}}\",\"{{sanction_type}}\",\"{{reason}}\",\"{{duration}}\"]', 'moderation', '1', '2026-06-01 10:41:51', '2026-06-01 10:41:51'),
('7', 'newsletter.confirmation', 'Newsletter : confirmation', 'Email de double-opt-in pour confirmer l\'inscription à la newsletter.', '[\"{{site_name}}\",\"{{confirm_url}}\"]', 'newsletter', '1', '2026-06-01 10:41:51', '2026-06-01 10:41:51');
INSERT INTO `nf_email_template_translations` (`template_id`, `lang`, `subject`, `body`, `updated_at`) VALUES
('1', 'de', 'Bestätige dein Konto auf {{site_name}}', '<p>Hallo <strong>{{username}}</strong>,</p><p>Willkommen auf <strong>{{site_name}}</strong>! Um dein Konto zu aktivieren, klicke auf den folgenden Link:</p><p><a href=\"{{validation_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Mein Konto aktivieren</a></p><p>Falls die Schaltfläche nicht funktioniert, kopiere diese URL in deinen Browser:<br><code>{{validation_url}}</code></p><p>Falls du diese Registrierung nicht veranlasst hast, ignoriere diese E-Mail einfach.</p>', '2026-06-11 09:08:07'),
('1', 'en', 'Confirm your account on {{site_name}}', '<p>Hello <strong>{{username}}</strong>,</p><p>Welcome to <strong>{{site_name}}</strong>! To activate your account, click the link below:</p><p><a href=\"{{validation_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Activate my account</a></p><p>If the button does not work, copy and paste this URL into your browser:<br><code>{{validation_url}}</code></p><p>If you did not request this registration, simply ignore this email.</p>', '2026-06-11 09:08:07'),
('1', 'es', 'Confirma tu cuenta en {{site_name}}', '<p>Hola <strong>{{username}}</strong>,</p><p>¡Bienvenido/a a <strong>{{site_name}}</strong>! Para activar tu cuenta, haz clic en el siguiente enlace:</p><p><a href=\"{{validation_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Activar mi cuenta</a></p><p>Si el botón no funciona, copia y pega esta URL en tu navegador:<br><code>{{validation_url}}</code></p><p>Si no has solicitado este registro, simplemente ignora este correo.</p>', '2026-06-11 09:08:07'),
('1', 'fr', 'Validation de votre compte sur {{site_name}}', '<p>Bonjour <strong>{{username}}</strong>,</p><p>Bienvenue sur <strong>{{site_name}}</strong> ! Pour activer ton compte, clique sur le lien ci-dessous :</p><p><a href=\"{{validation_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Valider mon compte</a></p><p>Si le bouton ne fonctionne pas, copie-colle cette URL dans ton navigateur :<br><code>{{validation_url}}</code></p><p>Si tu n\'es pas à l\'origine de cette inscription, ignore simplement cet email.</p>', '2026-06-01 10:41:51'),
('1', 'it', 'Conferma il tuo account su {{site_name}}', '<p>Ciao <strong>{{username}}</strong>,</p><p>Benvenuto/a su <strong>{{site_name}}</strong>! Per attivare il tuo account, clicca sul link qui sotto:</p><p><a href=\"{{validation_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Attiva il mio account</a></p><p>Se il pulsante non funziona, copia e incolla questo URL nel tuo browser:<br><code>{{validation_url}}</code></p><p>Se non sei stato tu a registrarti, ignora semplicemente questa email.</p>', '2026-06-11 09:08:07'),
('1', 'pt', 'Confirma a tua conta em {{site_name}}', '<p>Olá <strong>{{username}}</strong>,</p><p>Bem-vindo(a) a <strong>{{site_name}}</strong>! Para ativar a tua conta, clica no link abaixo:</p><p><a href=\"{{validation_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Ativar a minha conta</a></p><p>Se o botão não funcionar, copia e cola este URL no teu navegador:<br><code>{{validation_url}}</code></p><p>Se não foste tu a fazer este registo, ignora simplesmente este email.</p>', '2026-06-11 09:08:07'),
('2', 'de', 'Passwort zurücksetzen — {{site_name}}', '<p>Hallo <strong>{{username}}</strong>,</p><p>Du hast auf <strong>{{site_name}}</strong> das Zurücksetzen deines Passworts angefordert.</p><p><a href=\"{{reset_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Mein Passwort zurücksetzen</a></p><p>Dieser Link ist nur begrenzt gültig. Falls du diese Anfrage nicht gestellt hast, ignoriere diese E-Mail — dein Passwort wird nicht geändert.</p>', '2026-06-11 09:08:07'),
('2', 'en', 'Password reset — {{site_name}}', '<p>Hello <strong>{{username}}</strong>,</p><p>You requested a password reset on <strong>{{site_name}}</strong>.</p><p><a href=\"{{reset_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Reset my password</a></p><p>This link is valid for a limited time. If you did not make this request, ignore this email — your password will not be changed.</p>', '2026-06-11 09:08:07'),
('2', 'es', 'Restablecer contraseña — {{site_name}}', '<p>Hola <strong>{{username}}</strong>,</p><p>Has solicitado restablecer tu contraseña en <strong>{{site_name}}</strong>.</p><p><a href=\"{{reset_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Restablecer mi contraseña</a></p><p>Este enlace es válido durante un tiempo limitado. Si no has realizado esta solicitud, ignora este correo — tu contraseña no se modificará.</p>', '2026-06-11 09:08:07'),
('2', 'fr', 'Réinitialisation de mot de passe — {{site_name}}', '<p>Bonjour <strong>{{username}}</strong>,</p><p>Tu as demandé une réinitialisation de mot de passe sur <strong>{{site_name}}</strong>.</p><p><a href=\"{{reset_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Réinitialiser mon mot de passe</a></p><p>Ce lien est valide pendant une durée limitée. Si tu n\'es pas à l\'origine de cette demande, ignore cet email — ton mot de passe ne sera pas modifié.</p>', '2026-06-01 10:41:51'),
('2', 'it', 'Reimpostazione della password — {{site_name}}', '<p>Ciao <strong>{{username}}</strong>,</p><p>Hai richiesto la reimpostazione della password su <strong>{{site_name}}</strong>.</p><p><a href=\"{{reset_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Reimposta la mia password</a></p><p>Questo link è valido per un periodo limitato. Se non sei stato tu a fare questa richiesta, ignora questa email — la tua password non verrà modificata.</p>', '2026-06-11 09:08:07'),
('2', 'pt', 'Redefinição de palavra-passe — {{site_name}}', '<p>Olá <strong>{{username}}</strong>,</p><p>Solicitaste a redefinição da tua palavra-passe em <strong>{{site_name}}</strong>.</p><p><a href=\"{{reset_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Redefinir a minha palavra-passe</a></p><p>Este link é válido por tempo limitado. Se não fizeste este pedido, ignora este email — a tua palavra-passe não será alterada.</p>', '2026-06-11 09:08:07'),
('3', 'de', 'Du wurdest erwähnt: {{topic_title}}', '<p>Hallo <strong>{{username}}</strong>,</p><p><strong>{{mentioner}}</strong> hat dich im Thema « {{topic_title}} » auf <strong>{{site_name}}</strong> erwähnt.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Thema ansehen</a></p>', '2026-06-11 09:08:07'),
('3', 'en', 'You were mentioned: {{topic_title}}', '<p>Hello <strong>{{username}}</strong>,</p><p><strong>{{mentioner}}</strong> mentioned you in the topic « {{topic_title}} » on <strong>{{site_name}}</strong>.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">View the topic</a></p>', '2026-06-11 09:08:07'),
('3', 'es', 'Te han mencionado: {{topic_title}}', '<p>Hola <strong>{{username}}</strong>,</p><p><strong>{{mentioner}}</strong> te ha mencionado en el tema « {{topic_title}} » en <strong>{{site_name}}</strong>.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Ver el tema</a></p>', '2026-06-11 09:08:07'),
('3', 'fr', 'Tu as été mentionné(e) : {{topic_title}}', '<p>Bonjour <strong>{{username}}</strong>,</p><p><strong>{{mentioner}}</strong> t\'a mentionné(e) dans le sujet « {{topic_title}} » sur <strong>{{site_name}}</strong>.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Voir le sujet</a></p>', '2026-06-01 10:41:51'),
('3', 'it', 'Sei stato menzionato: {{topic_title}}', '<p>Ciao <strong>{{username}}</strong>,</p><p><strong>{{mentioner}}</strong> ti ha menzionato nella discussione « {{topic_title}} » su <strong>{{site_name}}</strong>.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Vedi la discussione</a></p>', '2026-06-11 09:08:07'),
('3', 'pt', 'Foste mencionado: {{topic_title}}', '<p>Olá <strong>{{username}}</strong>,</p><p><strong>{{mentioner}}</strong> mencionou-te no tópico « {{topic_title}} » em <strong>{{site_name}}</strong>.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Ver o tópico</a></p>', '2026-06-11 09:08:07'),
('4', 'de', 'Neue Antwort: {{topic_title}}', '<p>Hallo <strong>{{username}}</strong>,</p><p>Du folgst dem Thema « {{topic_title}} » auf <strong>{{site_name}}</strong>. Es hat soeben eine neue Antwort von <strong>{{author}}</strong> erhalten.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Antwort ansehen</a></p><p style=\"color:#888;font-size:13px;\">Du kannst dich auf der Themenseite abmelden.</p>', '2026-06-11 09:08:07'),
('4', 'en', 'New reply: {{topic_title}}', '<p>Hello <strong>{{username}}</strong>,</p><p>You are following the topic « {{topic_title}} » on <strong>{{site_name}}</strong>. It just received a new reply from <strong>{{author}}</strong>.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">View the reply</a></p><p style=\"color:#888;font-size:13px;\">You can unsubscribe from the topic page.</p>', '2026-06-11 09:08:07'),
('4', 'es', 'Nueva respuesta: {{topic_title}}', '<p>Hola <strong>{{username}}</strong>,</p><p>Sigues el tema « {{topic_title}} » en <strong>{{site_name}}</strong>. Acaba de recibir una nueva respuesta de <strong>{{author}}</strong>.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Ver la respuesta</a></p><p style=\"color:#888;font-size:13px;\">Puedes darte de baja desde la página del tema.</p>', '2026-06-11 09:08:07'),
('4', 'fr', 'Nouvelle réponse : {{topic_title}}', '<p>Bonjour <strong>{{username}}</strong>,</p><p>Tu suis le sujet « {{topic_title}} » sur <strong>{{site_name}}</strong>. Il vient de recevoir une nouvelle réponse de <strong>{{author}}</strong>.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Voir la réponse</a></p><p style=\"color:#888;font-size:13px;\">Tu peux te désabonner depuis la page du sujet.</p>', '2026-06-01 10:41:51'),
('4', 'it', 'Nuova risposta: {{topic_title}}', '<p>Ciao <strong>{{username}}</strong>,</p><p>Stai seguendo la discussione « {{topic_title}} » su <strong>{{site_name}}</strong>. Ha appena ricevuto una nuova risposta da <strong>{{author}}</strong>.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Vedi la risposta</a></p><p style=\"color:#888;font-size:13px;\">Puoi annullare l\'iscrizione dalla pagina della discussione.</p>', '2026-06-11 09:08:07'),
('4', 'pt', 'Nova resposta: {{topic_title}}', '<p>Olá <strong>{{username}}</strong>,</p><p>Estás a seguir o tópico « {{topic_title}} » em <strong>{{site_name}}</strong>. Acabou de receber uma nova resposta de <strong>{{author}}</strong>.</p><p><a href=\"{{topic_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Ver a resposta</a></p><p style=\"color:#888;font-size:13px;\">Podes cancelar a subscrição na página do tópico.</p>', '2026-06-11 09:08:07'),
('5', 'de', 'Neue Nachricht in: {{talk_name}}', '<p>Hallo <strong>{{username}}</strong>,</p><p>Du hast eine neue Nachricht von <strong>{{author}}</strong> in der Unterhaltung « {{talk_name}} » auf <strong>{{site_name}}</strong> erhalten.</p><p><a href=\"{{talk_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Nachricht lesen</a></p>', '2026-06-11 09:08:07'),
('5', 'en', 'New message in: {{talk_name}}', '<p>Hello <strong>{{username}}</strong>,</p><p>You received a new message from <strong>{{author}}</strong> in the conversation « {{talk_name}} » on <strong>{{site_name}}</strong>.</p><p><a href=\"{{talk_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Read the message</a></p>', '2026-06-11 09:08:07'),
('5', 'es', 'Nuevo mensaje en: {{talk_name}}', '<p>Hola <strong>{{username}}</strong>,</p><p>Has recibido un nuevo mensaje de <strong>{{author}}</strong> en la conversación « {{talk_name}} » en <strong>{{site_name}}</strong>.</p><p><a href=\"{{talk_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Leer el mensaje</a></p>', '2026-06-11 09:08:07'),
('5', 'fr', 'Nouveau message dans : {{talk_name}}', '<p>Bonjour <strong>{{username}}</strong>,</p><p>Tu as reçu un nouveau message de <strong>{{author}}</strong> dans la conversation « {{talk_name}} » sur <strong>{{site_name}}</strong>.</p><p><a href=\"{{talk_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Lire le message</a></p>', '2026-06-01 10:41:51'),
('5', 'it', 'Nuovo messaggio in: {{talk_name}}', '<p>Ciao <strong>{{username}}</strong>,</p><p>Hai ricevuto un nuovo messaggio da <strong>{{author}}</strong> nella conversazione « {{talk_name}} » su <strong>{{site_name}}</strong>.</p><p><a href=\"{{talk_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Leggi il messaggio</a></p>', '2026-06-11 09:08:07'),
('5', 'pt', 'Nova mensagem em: {{talk_name}}', '<p>Olá <strong>{{username}}</strong>,</p><p>Recebeste uma nova mensagem de <strong>{{author}}</strong> na conversa « {{talk_name}} » em <strong>{{site_name}}</strong>.</p><p><a href=\"{{talk_url}}\" style=\"display:inline-block;padding:8px 16px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Ler a mensagem</a></p>', '2026-06-11 09:08:07'),
('6', 'de', 'Moderationsmaßnahme für dein Konto — {{site_name}}', '<p>Hallo <strong>{{username}}</strong>,</p><p>Für dein Konto auf <strong>{{site_name}}</strong> wurde eine Maßnahme verhängt.</p><table style=\"border-collapse:collapse;margin:12px 0;\"><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Art</td><td style=\"padding:6px 12px;\">{{sanction_type}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Dauer</td><td style=\"padding:6px 12px;\">{{duration}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Grund</td><td style=\"padding:6px 12px;\">{{reason}}</td></tr></table><p>Falls du der Meinung bist, dass diese Entscheidung ungerechtfertigt ist, kannst du das Moderationsteam über die Kontaktseite erreichen.</p>', '2026-06-11 09:08:07'),
('6', 'en', 'Moderation sanction on your account — {{site_name}}', '<p>Hello <strong>{{username}}</strong>,</p><p>A sanction has been applied to your account on <strong>{{site_name}}</strong>.</p><table style=\"border-collapse:collapse;margin:12px 0;\"><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Type</td><td style=\"padding:6px 12px;\">{{sanction_type}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Duration</td><td style=\"padding:6px 12px;\">{{duration}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Reason</td><td style=\"padding:6px 12px;\">{{reason}}</td></tr></table><p>If you believe this decision is unjustified, you can contact the moderation team via the contact page.</p>', '2026-06-11 09:08:07'),
('6', 'es', 'Sanción de moderación en tu cuenta — {{site_name}}', '<p>Hola <strong>{{username}}</strong>,</p><p>Se ha aplicado una sanción a tu cuenta en <strong>{{site_name}}</strong>.</p><table style=\"border-collapse:collapse;margin:12px 0;\"><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Tipo</td><td style=\"padding:6px 12px;\">{{sanction_type}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Duración</td><td style=\"padding:6px 12px;\">{{duration}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Motivo</td><td style=\"padding:6px 12px;\">{{reason}}</td></tr></table><p>Si consideras que esta decisión es injustificada, puedes contactar con el equipo de moderación a través de la página de contacto.</p>', '2026-06-11 09:08:07'),
('6', 'fr', 'Sanction de modération sur ton compte — {{site_name}}', '<p>Bonjour <strong>{{username}}</strong>,</p><p>Une sanction a été appliquée à ton compte sur <strong>{{site_name}}</strong>.</p><table style=\"border-collapse:collapse;margin:12px 0;\"><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Type</td><td style=\"padding:6px 12px;\">{{sanction_type}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Durée</td><td style=\"padding:6px 12px;\">{{duration}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Motif</td><td style=\"padding:6px 12px;\">{{reason}}</td></tr></table><p>Si tu estimes que cette décision est injustifiée, tu peux contacter l\'équipe de modération via la page de contact.</p>', '2026-06-01 10:41:51'),
('6', 'it', 'Sanzione di moderazione sul tuo account — {{site_name}}', '<p>Ciao <strong>{{username}}</strong>,</p><p>È stata applicata una sanzione al tuo account su <strong>{{site_name}}</strong>.</p><table style=\"border-collapse:collapse;margin:12px 0;\"><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Tipo</td><td style=\"padding:6px 12px;\">{{sanction_type}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Durata</td><td style=\"padding:6px 12px;\">{{duration}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Motivo</td><td style=\"padding:6px 12px;\">{{reason}}</td></tr></table><p>Se ritieni che questa decisione sia ingiustificata, puoi contattare il team di moderazione tramite la pagina dei contatti.</p>', '2026-06-11 09:08:07'),
('6', 'pt', 'Sanção de moderação na tua conta — {{site_name}}', '<p>Olá <strong>{{username}}</strong>,</p><p>Foi aplicada uma sanção à tua conta em <strong>{{site_name}}</strong>.</p><table style=\"border-collapse:collapse;margin:12px 0;\"><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Tipo</td><td style=\"padding:6px 12px;\">{{sanction_type}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Duração</td><td style=\"padding:6px 12px;\">{{duration}}</td></tr><tr><td style=\"padding:6px 12px;background:#f5f5f5;font-weight:bold;\">Motivo</td><td style=\"padding:6px 12px;\">{{reason}}</td></tr></table><p>Se consideras que esta decisão é injustificada, podes contactar a equipa de moderação através da página de contacto.</p>', '2026-06-11 09:08:07'),
('7', 'de', 'Bestätige dein Newsletter-Abonnement — {{site_name}}', '<p>Hallo!</p><p>Um dein Abonnement des Newsletters von <strong>{{site_name}}</strong> abzuschließen, klicke auf die Schaltfläche unten:</p><p><a href=\"{{confirm_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Mein Abonnement bestätigen</a></p><p>Falls du dieses Abonnement nicht angefordert hast, ignoriere diese E-Mail einfach.</p>', '2026-06-11 09:08:07'),
('7', 'en', 'Confirm your newsletter subscription — {{site_name}}', '<p>Hi!</p><p>To complete your subscription to the <strong>{{site_name}}</strong> newsletter, click the button below:</p><p><a href=\"{{confirm_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Confirm my subscription</a></p><p>If you did not request this subscription, simply ignore this email.</p>', '2026-06-11 09:08:07'),
('7', 'es', 'Confirma tu suscripción a la newsletter — {{site_name}}', '<p>¡Hola!</p><p>Para completar tu suscripción a la newsletter de <strong>{{site_name}}</strong>, haz clic en el botón de abajo:</p><p><a href=\"{{confirm_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Confirmar mi suscripción</a></p><p>Si no has solicitado esta suscripción, simplemente ignora este correo.</p>', '2026-06-11 09:08:07'),
('7', 'fr', 'Confirme ton inscription à la newsletter — {{site_name}}', '<p>Salut !</p><p>Pour finaliser ton inscription à la newsletter de <strong>{{site_name}}</strong>, clique sur le bouton ci-dessous :</p><p><a href=\"{{confirm_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Confirmer mon inscription</a></p><p>Si tu n\'es pas à l\'origine de cette inscription, ignore simplement cet email.</p>', '2026-06-01 10:41:51'),
('7', 'it', 'Conferma la tua iscrizione alla newsletter — {{site_name}}', '<p>Ciao!</p><p>Per completare la tua iscrizione alla newsletter di <strong>{{site_name}}</strong>, clicca sul pulsante qui sotto:</p><p><a href=\"{{confirm_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Conferma la mia iscrizione</a></p><p>Se non sei stato tu a richiedere questa iscrizione, ignora semplicemente questa email.</p>', '2026-06-11 09:08:07'),
('7', 'pt', 'Confirma a tua subscrição da newsletter — {{site_name}}', '<p>Olá!</p><p>Para concluir a tua subscrição da newsletter de <strong>{{site_name}}</strong>, clica no botão abaixo:</p><p><a href=\"{{confirm_url}}\" style=\"display:inline-block;padding:10px 20px;background:#03c1a2;color:#fff;text-decoration:none;border-radius:4px;\">Confirmar a minha subscrição</a></p><p>Se não foste tu a fazer esta subscrição, ignora simplesmente este email.</p>', '2026-06-11 09:08:07');
